import numpy as np
from scipy.ndimage import map_coordinates, sobel
class FlowBoard:
 def __init__(self):self.prev=None;self.pts=np.array([[174.,218.],[194.,213.]])
 def track(self,image):
  im=np.mean(image,2)/255
  if self.prev is not None:
   for j,pt in enumerate(self.pts):
    yy,xx=np.mgrid[-4:5,-4:5];coords=np.array([yy+pt[1],xx+pt[0]])
    old=map_coordinates(self.prev,coords,order=1);gx=map_coordinates(sobel(self.prev,axis=1)/8,coords,order=1);gy=map_coordinates(sobel(self.prev,axis=0)/8,coords,order=1);G=np.c_[gx.ravel(),gy.ravel()];move=np.zeros(2)
    for _ in range(5):
     new=map_coordinates(im,coords+move[::-1,None,None],order=1);delta=np.linalg.lstsq(G,(old-new).ravel(),rcond=.01)[0];move+=np.clip(delta,-1,1)
    self.pts[j]+=np.clip(move,-3,3)
  self.prev=im
  dx,dy=self.pts[0]-self.pts[1];p=np.arctan2(-74*dy-18*dx,73*dx+2.5*dy)
  if p<-np.pi/2:p+=np.pi
  if p>np.pi/2:p-=np.pi
  return p,self.pts.copy()
if __name__=='__main__':
 from PIL import Image
 import sys
 b=FlowBoard();tag=sys.argv[1]
 for i in range(100):
  try:im=np.array(Image.open('/app/output/frame_'+tag+'_%03d.png'%i))
  except:break
  p,pts=b.track(im)
  if i%5==0: print(i,round(p,3),pts.round(2))
